result.text:
      return;
    case "paste-text":
      openPasteModal();
      return;
    case "import-email":
      pickEmails();
      return;
    case "paste-mail":
      openMailPasteModal();
      return;
    case "use-mail":
      useMail(id);
      return;
    case "delete-mail": {
      const ok = await confirmDialog({
        title: "Borrar el correo",
        message: "Se quita de la lista. Las facturas que ya hayas guardado desde él no se tocan.",
        confirm: "Sí, borrar",
        danger: true,
      });
      if (!ok) return;
      deleteMessage(id);
      toast("Correo borrado.");
      render();
      return;
    }
    case "test-ai":
      testAi();
      return;
    case "export-csv":
      exportCsv();
      return;
    case "export-json":
      exportBackup();
      return;
    case "import-json":
      askImportBackup();
      return;
    case "settings":
      openSettings();
      return;
    case "clear-all": {
      const ok = await confirmDialog({
        title: "Borrar todo",
        message: "Se borrarán todas las facturas y todos los proveedores. Descarga antes una copia si no estás seguro.",
        confirm: "Sí, borrar todo",
        danger: true,
      });
      if (!ok) return;
      clearAll();
      closeModal();
      toast("Todo borrado. Empiezas de cero.");
      render();
      return;
    }
    case "seed-demo": {
      const ok = await confirmDialog({
        title: "Cargar datos de ejemplo",
        message: "Se añadirán 5 proveedores inventados y 11 facturas para que veas cómo funciona. Podrás borrarlo todo después.",
        confirm: "Sí, cargar el ejemplo",
      });
      if (!ok) return;
      seedDemo();
      toast("Datos de ejemplo cargados.");
      render();
      return;
    }
    case "retry-job": {
      const job = ui.jobs.find((j) => j.id === id);
      if (job) {
        job.state = "queued";
        job.pct = 0;
        job.error = "";
        paintIngest();
        runQueue();
      }
      return;
    }
    case "acc-tab": {
      ui.conta.tab = id || "diario";
      render();
      return;
    }
    case "acc-all": {
      ui.conta.range = "all";
      ui.conta.from = "";
      ui.conta.to = "";
      render();
      return;
    }
    case "acc-apertura":
    case "acc-settings": {
      accAperturaModal();
      return;
    }
    case "acc-save-apertura": {
      saveApertura();
      return;
    }
    case "export-acc-csv": {
      exportAccCsv();
      return;
    }
    default:
      return;
  }
}

